export function createAdditionalRules(): Rule[] {
  const critical = new Set([78, 89, 94, 95, 917, 1336]);
  const high = new Set(["xss", "deserialization", "transport", "xxe", "ssrf"]);
  return Object.entries(groups).flatMap(([family, specs]) => specs.map(([id, title, cwe, category, pattern, recommendation]) => ({
    id, title, pattern, category, recommendation, languages: languages[family],
    cwe: `CWE-${cwe}`, owasp: categoryInfo[category][0],
    description: `${title}. ${categoryInfo[category][1]} Проверьте источник данных и условия применения.`,
    severity: (critical.has(cwe) ? "critical" : high.has(category) || cwe === 306 ? "high" : "medium") as Severity,
    confidence: "medium" as const,
    references: [`https://cwe.mitre.org/data/definitions/${cwe}.html`],
  })));
}
